"use strict";(self.rspackChunkboser_frontend=self.rspackChunkboser_frontend||[]).push([[400],{86035(t){t.exports=JSON.parse('{"mining-stats.tuner.stage.stabilizing_temperature":"正在稳定温度","mining-stats.tuner.stage.optimizing_efficiency":"正在优化能效","mining-stats.tuner.stage.testing_performance_profile":"正在测试性能配置","mining-stats.tuner.stage.tuning_individual_chips":"正在逐颗调优芯片","mining-stats.tuner.stage.continuous_tuning":"持续调优中","mining-stats.tuner.stage.stable":"稳定","mining-stats.tuner.stage.not_running":"调优器未运行","mining-stats.tuner.stage.running_with_fixed_settings":"以固定参数运行","mining-stats.dps.disabled":"已禁用","mining-stats.dps.initial_power_target":"已启用","mining-stats.dps.initial_hashrate_target":"已启用","mining-stats.dps.lowered_power_target":"目标功耗已调整为 {powerTargetW, number, ::.00} W","mining-stats.dps.lowered_hashrate_target":"目标算力已调整为 {hashrate}/s","mining-stats.dps.mining_shutdown":"挖矿已关闭，将于 {countdown} 后重新启动","advanced-settings.allow_disabling_hashboards_on_nopic_miners.title":"在无 PIC 矿机上禁用算力板","advanced-settings.allow_disabling_hashboards_on_nopic_miners.description":"允许无 PIC 矿机在算力板损坏的情况下，通过绕过默认的安全关机机制继续挖矿。仅在您了解相关风险时使用。","advanced-settings.allow_missing_voltage_feedback.title":"允许缺失电压反馈","advanced-settings.allow_missing_voltage_feedback.description":"允许矿机在没有来自 PIC 或电源（PSU）电压反馈的情况下启动。此操作会禁用电压校验与短路检测。仅在您了解相关风险时使用。","advanced-settings.cgminer_readonly.title":"CGMiner API 只读模式","advanced-settings.cgminer_readonly.description":"启用后，所有具有修改权限的 CGMiner API 指令都将被拦截。这包括矿池管理（添加/删除/替换/启用/禁用/切换）以及挖矿控制（暂停/恢复）。","advanced-settings.defrost_temperature_limit_c.title":"预热温度上限","advanced-settings.defrost_temperature_limit_c.description":"达到预热温度时，矿机将停止对算力板加热并继续开机启动。浸没式与水冷矿机的推荐值为 10°C；风冷矿机请根据您的实际运维情况设置合适温度。请注意，机器温度过低时开机可能会损害硬件寿命与健康。","advanced-settings.defrost_timeout_mode.title":"预热超时模式","advanced-settings.defrost_timeout_mode.description":"控制算力板预热程序的运行时间。不限时表示持续预热直至算力板变暖；定时表示预热将在达到预热超时时长后停止。","advanced-settings.defrost_timeout_mode.option.indefinite":"不限时","advanced-settings.defrost_timeout_mode.option.timed":"定时","advanced-settings.defrost_timeout_s.title":"预热超时时长","advanced-settings.defrost_timeout_s.description":"算力板预热程序的超时时间","advanced-settings.enable_continuous_tuning.title":"持续微调","advanced-settings.enable_continuous_tuning.description":"在完成初始调优后，持续对矿机进行微调。","advanced-settings.enable_defrost.title":"算力板预热","advanced-settings.enable_defrost.description":"预热处于低温状态的算力板，以便在低温环境下启动挖矿。","advanced-settings.ignore_internal_chip_temperature.title":"无视芯片温度安全检查","advanced-settings.ignore_internal_chip_temperature.description":"禁用当内部芯片达到“危险（DANGEROUS）”温度时触发的自动暂停功能。可能会导致设备过热或硬件损坏。","advanced-settings.mdns_enabled.title":"通过 mDNS 广播宣告","advanced-settings.mdns_enabled.description":"启用后，矿机将通过 mDNS/DNS-SD 广播宣告其 Web 界面与 API，从而无需知晓其 IP 地址即可在局域网中被发现。大型矿机默认禁用此项，因为在扁平化矿场网络中链路本地多播会泛洪到每一个端口。小型矿机默认启用；设备的实时 schema 会报告其对应平台的默认值。","advanced-settings.min_fan_pwm.title":"风扇最低 PWM","advanced-settings.min_fan_pwm.description":"当“风扇最低 PWM 模式”设置为手动（Manual）时所使用的最低风扇 PWM 百分比。","advanced-settings.min_fan_pwm_mode.title":"风扇最低 PWM 模式","advanced-settings.min_fan_pwm_mode.description":"控制矿机启动时如何确定最低风扇 PWM 占空比。在“Auto”（自动）模式下，矿机会运行风扇自动配置以测定最低转速（RPM）；在“Manual”（手动）模式下，则直接使用“Min Fan PWM”中设定的固定数值。","advanced-settings.min_fan_pwm_mode.option.auto":"自动","advanced-settings.min_fan_pwm_mode.option.manual":"手动","advanced-settings.normal_ramping_time_down_mode.title":"常规降频时间模式","advanced-settings.normal_ramping_time_down_mode.description":"控制关机或重启过程中的功率降频时间。默认使用内置计时逻辑；在“自定义（Custom）”模式下，则应用“常规降频时间”中设定的数值。","advanced-settings.normal_ramping_time_down_mode.option.unchanged":"内置","advanced-settings.normal_ramping_time_down_mode.option.custom":"自定义","advanced-settings.normal_ramping_time_down_s.title":"常规降频时间","advanced-settings.normal_ramping_time_down_s.description":"控制矿机降低频率的速度。该数值越低，可能会增加元器件的负荷并缩短设备寿命；该数值过高时，在矿机关机和重启期间可能会受到限制。","advanced-settings.normal_ramping_time_up_mode.title":"常规爬升时间模式","advanced-settings.normal_ramping_time_up_mode.description":"控制开机或重启后（非暂停/恢复）的功率爬升时间。默认使用内置计时逻辑；在“自定义（Custom）”模式下，则应用“常规爬升时间”中设定的数值。","advanced-settings.normal_ramping_time_up_mode.option.unchanged":"内置","advanced-settings.normal_ramping_time_up_mode.option.custom":"自定义","advanced-settings.normal_ramping_time_up_s.title":"常规爬升时间","advanced-settings.normal_ramping_time_up_s.description":"控制开机或重启后（非暂停/恢复）矿机功率爬升的速度。该值越低，可能会增加元器件的负荷并缩短设备寿命。","advanced-settings.overheat_recovery_mode.title":"过热后自动恢复","advanced-settings.overheat_recovery_mode.description":"覆盖矿机因达到“危险”温度而暂停后的处理行为。默认情况下，风冷和浸没式矿机会在冷却后自动恢复运行，但水冷矿机默认禁用此功能（以防止在冷却水未循环流动时造成损坏）。","advanced-settings.overheat_recovery_mode.option.unchanged":"内置","advanced-settings.overheat_recovery_mode.option.disabled":"禁用","advanced-settings.overheat_recovery_mode.option.enabled":"启用","advanced-settings.rambo_mode.title":"兰博模式（强行容错模式）","advanced-settings.rambo_mode.description":"兰博模式是一种“容错级别”。开启后将忽略芯片与电源（PSU）通信中的某些错误。","advanced-settings.rambo_mode.option.disabled":"禁用","advanced-settings.rambo_mode.option.cautious":"谨慎","advanced-settings.rambo_mode.option.maximum":"最大","advanced-settings.start_cooldown_mode.title":"启动前冷却模式","advanced-settings.start_cooldown_mode.description":"控制挖矿启动或恢复前执行的冷却逻辑。默认情况下，矿机会等待芯片降至预设温度。“Timed（定时）”模式会对总等待时间设定上限；“Disabled（禁用）”模式则完全跳过冷却等待。芯片温度过高时直接启动可能会损害硬件寿命与健康。","advanced-settings.start_cooldown_mode.option.unchanged":"内置","advanced-settings.start_cooldown_mode.option.timed":"定时","advanced-settings.start_cooldown_mode.option.disabled":"禁用","advanced-settings.start_cooldown_timeout_s.title":"启动前冷却超时时长","advanced-settings.start_cooldown_timeout_s.description":"挖矿启动或恢复前，矿机用于冷却芯片的最长时间。","advanced-settings.startup_delay_max_s.title":"最大启动延迟","advanced-settings.startup_delay_max_s.description":"挖矿启动前的最大随机延迟时间。每次矿机启动或从暂停状态恢复时，会在 0 到该最大值之间随机选取一个数值。适用于在矿场断电/电网事件后错峰分批启动机器。"}')}}]);